#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# patch_hook_alana.py -- hook 2-linhas formato Alana ("frase" / "A Shopee:")
# + fontes header env (NOME_FONT/HANDLE_FONT). Backup + py_compile + idempotente + restaura.
# Rode na VPS:  cd ~/jarvis && .venv/bin/python patch_hook_alana.py
import base64, py_compile, shutil, sys, time
from pathlib import Path
ALVO = Path(__file__).resolve().parent / "agents/narrated_video_agent.py"
PARES = [('', ''), ('', ''), ('', ''), ('', '')]
def main():
    if not ALVO.exists():
        print("nao achei", ALVO); return 1
    txt = ALVO.read_text(encoding="utf-8").replace("\r\n", "\n")
    pares = [(base64.b64decode(o).decode(), base64.b64decode(n).decode()) for o, n in PARES]
    if all(n in txt for _, n in pares):
        print("JA APLICADO"); return 0
    novo = txt
    for old, new in pares:
        if new in novo:
            continue
        if old not in novo:
            print("ABORTADO: bloco nao encontrado (VPS divergente):")
            print("   " + old.strip().splitlines()[0][:90]); return 2
        if novo.count(old) != 1:
            print("ABORTADO: bloco ambiguo (!=1x):")
            print("   " + old.strip().splitlines()[0][:90]); return 2
        novo = novo.replace(old, new)
    bak = ALVO.with_suffix(ALVO.suffix + ".bak_" + time.strftime("%Y%m%d_%H%M%S"))
    shutil.copy2(ALVO, bak)
    ALVO.write_text(novo, encoding="utf-8")
    try:
        py_compile.compile(str(ALVO), doraise=True)
    except Exception as e:
        shutil.copy2(bak, ALVO)
        print("py_compile falhou, RESTAUREI:", e); return 3
    print("APLICADO (backup", bak.name, "). Reinicie: systemctl restart jarvis")
    return 0
if __name__ == "__main__":
    sys.exit(main())
